intentos.respuesta_cruda:
{
  "sql": "SELECT t1.product_category_name_english, AVG(t2.review_score) AS avg_review_score, SUM(CASE WHEN t3.entrega_con_retraso = 1 THEN 1 ELSE 0 END) * 100.0 / COUNT(t3.order_id) AS pct_retrasos FROM product_category_translation t1 LEFT JOIN order_reviews t2 ON t2.order_id IN (SELECT order_id FROM order_items WHERE product_id IN (SELECT product_id FROM products WHERE product_category_name = t1.product_category_name)) LEFT JOIN vw_entregas_retrasos t3 ON t3.order_id = t2.order_id WHERE t2.review_score IS NOT NULL GROUP BY t1.product_category_name_english HAVING COUNT(t2.review_id) >= 100 AND AVG(t2.review_score) < (SELECT AVG(review_score) FROM order_reviews WHERE review_score IS NOT NULL) AND SUM(CASE WHEN t3.entrega_con_retraso = 1 THEN 1 ELSE 0 END) * 100.0 / COUNT(t3.order_id) < (SELECT SUM(CASE WHEN entrega_con_retraso = 1 THEN 1 ELSE 0 END) * 100.0 / COUNT(order_id) FROM vw_entregas_retrasos WHERE order_delivered_customer_date IS NOT NULL)"
}
